var i={en:`100,000 devices reconnect, producing 100,000 readings/minute. Critical anomalies should appear within 10 s; long-term raw storage is too expensive.`,ua:`100 000 пристроїв перепідключаються, надсилаючи 100 000 вимірів/хв. Критичні відхилення мають з’явитись до 10 с; сире довгострокове сховище надто дороге.`};var n={en:[`Add buffering, partitioning and load shedding without losing safety alarms.`,`Separate real-time rules from downsampled historical analytics.`,`Estimate storage costs and define reconnect load/SLO tests.`],ua:[`Додай буферизацію, партиції й контроль навантаження без втрати тривог.`,`Відокрем правила реального часу від агрегованої історії.`,`Оціни вартість сховища й навантажувальні тести/SLO.`]};var t=[{en:`Safety alarms outrank bulk backfill traffic.`,ua:`Тривоги важливіші за масову історичну передачу.`},{en:`Raw and downsampled retention have distinct policies.`,ua:`Сирі та агреговані дані мають окремі правила зберігання.`}];var s={scenario:i,tasks:n,checks:t};export{t as checks,s as default,i as scenario,n as tasks};